import{_ as t,o,c as n,ag as i}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-08（智能自学）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/intelligence-self-learning/science-daily-2026-10-08.md","filePath":"topics/intelligence-self-learning/science-daily-2026-10-08.md"}'),a={name:"topics/intelligence-self-learning/science-daily-2026-10-08.md"};function r(l,e,c,s,d,u){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="科学日报-·-2026-10-08-智能自学" tabindex="-1">科学日报 · 2026-10-08（智能自学） <a class="header-anchor" href="#科学日报-·-2026-10-08-智能自学" aria-label="Permalink to &quot;科学日报 · 2026-10-08（智能自学）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-08.md</code> — 第31期</p></blockquote><hr><h2 id="sherpa-教大模型-因人施教-arxiv-2610-08778" tabindex="-1">Sherpa：教大模型&quot;因人施教&quot;（arXiv:2610.08778） <a class="header-anchor" href="#sherpa-教大模型-因人施教-arxiv-2610-08778" aria-label="Permalink to &quot;Sherpa：教大模型&quot;因人施教&quot;（arXiv:2610.08778）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-08.md</code> ｜ arXiv: 2610.08778</p></blockquote><ul><li>问题：&quot;会解&quot;不等于&quot;会教&quot;；把 LLM 训成教师的方法依赖示范、偏好数据或<strong>预先规定的教学标准</strong>，这些信号<strong>不扎根于具体学习者真实的学习结果</strong>，而有效策略又因人而异。</li><li>方法：<strong>Sherpa</strong> 是多轮强化学习框架——用 LLM 实例化多个具有不同学习偏好的**&quot;学生原型&quot;<strong>，训练教师通过</strong>直接最大化学生学习成果**来调整讲解。</li><li>数据：受训教师在所有原型上平均把学生成绩提升 <strong>20.5 个百分点</strong>；<strong>MathTutorBench</strong> 教学分从 <strong>52.5% → 79.2%</strong>；人类研究显示受训教师更受偏好。</li><li>洞察：<strong>把&quot;学习成效&quot;直接写进优化目标</strong>，而非代理指标（&quot;讲得像好老师&quot;）。与本库自学方法论同构——衡量学习的唯一硬指标是<strong>可迁移的产出/复现能力</strong>，不是&quot;看起来懂了&quot;。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/intelligence-self-learning/index.md</code> ｜ 第31期 AI 板块</p></blockquote><p>关键词：自适应教学、学生原型、多轮强化学习、学习成效、MathTutorBench、因人施教、代理指标 关联：<code>topics/intelligence-self-learning/single-point-breakthrough.md</code>（以产出衡量学习）、<code>topics/intelligence-self-learning/knowledge-grafting-meaningful-learning.md</code>、<code>topics/ai-system-architecture/science-daily-2026-10-08.md</code>（Agent in a Bottle：把&quot;会&quot;固化为资产）</p>',9)])])}const q=t(a,[["render",r]]);export{p as __pageData,q as default};
